def toposort(graph):
    visited, order = set(), []
    def dfs(n):
        if n in visited: return
        visited.add(n)
        for m in graph.get(n, []):
            dfs(m)
        order.append(n)
    for node in graph: dfs(node)
    return list(reversed(order))

