def toposort(graph):
    WHITE, GREY, BLACK = 0, 1, 2
    color = {n: WHITE for n in graph}
    order = []
    def dfs(n):
        if color.get(n) == GREY: raise ValueError('cycle')
        if color.get(n) == BLACK: return
        color[n] = GREY
        for m in graph.get(n, []):
            dfs(m)
        color[n] = BLACK
